  x.fillStyle='#030711';x.beginPath();x.ellipse(0,-size*.05,size*.42,size*.24,0,0,Math.PI*2);x.fill();x.strokeStyle=color;x.stroke();
  x.fillStyle=accent;x.fillRect(-size*.24,-size*.08,size*.16,Math.max(2,size*.07));x.fillRect(size*.08,-size*.08,size*.16,Math.max(2,size*.07));
